135	  const by = (outcome: UpdateOutcome) => entries.filter((e) => e.outcome === outcome).map((e) => e.path);
136	  return {
137	    base,
138	    target,
139	    entries,
140	    take: by("take"),
141	    add: by("add"),
142	    delete: by("delete"),
143	    merge: by("merge"),
144	    kept: entries.filter((e) => e.outcome === "keep"),
145	  };
146	}
147	
148	/**
149	 * Paths present in the tree, under the paths the release owns, that the target
150	 * release does not ship.
151	 *
152	 * Broader than the plan's deletions: these include files inherited from releases
153	 * older than the base one, which no comparison of two releases can see. They are
154	 * reported, never acted on — the manifest cannot tell the adopter's own files
155	 * from abandoned template ones, so deleting on this list is how a person's
156	 * workflow vanishes. The notice names them; the update names them; a person
157	 * decides.
158	 */
159	export function leftoversOf(targetManifest: ReleaseManifest, treePaths: Iterable<string>): string[] {
160	  return noLongerShipped(targetManifest, treePaths);
161	}
162	
163	/**
164	 * The one sentence a report leads with, before any list.
165	 *
166	 * `mergeCount` is the plan's merge paths; the execution may resolve some cleanly,
167	 * so a report written after merging counts its own conflicts instead and passes
168	 * that number. Zero means nothing in this tree can collide with the release --
169	 * which is exactly the condition under which the update may merge itself.
170	 */
171	export function verdictSentence(base: string, target: string, mergeCount: number, keptCount: number): string {
172	  if (mergeCount === 0 && keptCount === 0) {
173	    return `Nothing in this tree collides with ${target}: the update applies itself, and no decision is needed on the way from ${base}.`;
174	  }
175	  return `Taking ${target} onto ${base} needs a decision here: ${mergeCount} file(s) changed on both sides, ${keptCount} more the plan will not touch without a person.`;
176	}

