1	/**
2	 * update-apply.ts — put an update plan onto a tree, and find out what really merges.
3	 *
4	 * The plan (`domain/machinery/update-plan.ts`) classifies every path; this module
5	 * performs what it proposes, inside a directory it is pointed at. The one judgement
6	 * it adds is the merge itself: a path marked `merge` — both sides changed it — is
7	 * resolved with `git merge-file`, the same three-way merge a normal git merge runs,
8	 * given the base content, the adopter's content, and the target content. The result
9	 * is either content both sides can live with, or content carrying conflict markers
10	 * and a report that a person (or an agent acting for one) is needed on that path.
11	 *
12	 * That is why the machinery's stop condition is measured here and not declared
13	 * upstream: whether BOTH sides changed a file says a merge is needed; running the
14	 * merge says whether it had a collision.
15	 *
16	 * ## Everything is decided before anything is written
17	 *
18	 * The merges all run in a scratch directory first, and the tree only sees whole
19	 * files after every path has resolved. A plan that half-applies is worse than one
20	 * that refuses outright: the tree would then say something no release ever shipped.
21	 * Refusal is total and answered with a `why`; the git status of the tree the run
22	 * works in is untouched by a refused plan.
23	 *
24	 * `treeRoot` is a directory this call writes into — in production the repository
25	 * checkout the workflow runs in, in tests a temp tree. Every path it touches must
26	 * already name a file in one of the two releases; anything else in the tree is the
27	 * adopter's, and this module never lists it, walks it, or writes beside it.
28	 */
29	import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
30	import { tmpdir } from "node:os";
31	import { basename, dirname, join, resolve, sep } from "node:path";
32	import type { UpdatePlan } from "../../../domain/machinery/update-plan.ts";
33	
34	/** What applying a plan did, as the pull request and the notices render it. */
35	export interface ApplyResult {
36	  /** Paths that took the target's content (plan: take), written. */
37	  readonly taken: readonly string[];
38	  /** Plan: add — paths created. */
39	  readonly added: readonly string[];
40	  /** Plan: delete — paths removed. */
41	  readonly removed: readonly string[];
42	  /** Plan: merge — paths whose three-way merge resolved with no conflict. */
43	  readonly merged: readonly string[];
44	  /** Plan: merge — paths whose merge collided, now carrying conflict markers. */
45	  readonly conflicts: readonly string[];
46	}
47	
48	/** Every path refuses together: no `why` means the tree holds the whole plan. */
49	export type Applied = { result: ApplyResult } | { why: string };
50	
51	/**
52	 * Apply `plan` to the tree at `treeRoot`.
53	 *
54	 * `base` and `target` are the two releases' contents; `ours` is what the tree holds
55	 * at the paths the plan cares about (the same map `planUpdate` read). Writes are
56	 * whole-file — the release ships files as they are, so an update is byte-for-byte
57	 * what the release carries, not a patch sequence.
58	 */
59	export function applyPlan(
60	  treeRoot: string,
61	  plan: UpdatePlan,
62	  base: ReadonlyMap<string, string>,
63	  target: ReadonlyMap<string, string>,
64	  ours: ReadonlyMap<string, string>,
65	): Applied {
66	  const root = resolve(treeRoot);
67	  /** Where `path` lands inside the tree, or null when it would escape it. */
68	  const inside = (path: string): string | null => {
69	    const destination = resolve(join(root, path));
70	    if (destination !== root && !destination.startsWith(root + sep)) return null;
71	    return destination;
72	  };
73	
74	  // Decide everything: content per path to write, paths to delete. The tree is
75	  // untouched until every decision has succeeded.
76	  const writes = new Map<string, string>();
77	  const deletes = new Set<string>();
78	  const taken: string[] = [];
79	  const added: string[] = [];
80	  const removed: string[] = [];
81	  const merged: string[] = [];
82	  const conflicts: string[] = [];
83	
84	  for (const path of plan.take) {
85	    const content = target.get(path);
86	    if (content === undefined) {
87	      return { why: `the target release does not carry \`${path}\`, which the plan says to take` };
88	    }
89	    writes.set(path, content);
90	    taken.push(path);
91	  }
92	  for (const path of plan.add) {
93	    const content = target.get(path);
94	    if (content === undefined) {
95	      return { why: `the target release does not carry \`${path}\`, which the plan says to add` };
96	    }
97	    // A path upstream adds where the plan says nothing is in the way is a file the
98	    // tree should not already hold; refuse to clobber one that appeared anyway.
99	    const destination = inside(path);
100	    if (destination === null) return { why: `\`${path}\` resolves outside the tree` };
101	    if (existsSync(destination)) {
102	      return { why: `\`${path}\` exists in the tree but the plan did not expect it` };
103	    }
104	    writes.set(path, content);
105	    added.push(path);
106	  }
107	  for (const path of plan.delete) {
108	    if (inside(path) === null) return { why: `\`${path}\` resolves outside the tree` };
109	    deletes.add(path);
110	    removed.push(path);
111	  }
112	
113	  const scratch = (() => {
114	    try {
115	      return mkdtempSync(join(tmpdir(), "atomaton-merge-"));
116	    } catch (error) {
117	      return null;
118	    }
119	  })();
120	  if (scratch === null) {
121	    return { why: `could not make a scratch directory for the merges` };
122	  }
123	  try {
124	    for (const path of plan.merge) {
125	      const baseContent = base.get(path);
126	      const oursContent = ours.get(path);
127	      const targetContent = target.get(path);
128	      if (baseContent === undefined || oursContent === undefined || targetContent === undefined) {
129	        return { why: `\`${path}\` is marked for a merge this run cannot read all three sides of` };
130	      }

