131	      const outcome = mergeFile(scratch, basename(path) || path, baseContent, oursContent, targetContent);
132	      if ("why" in outcome) return { why: outcome.why };
133	      writes.set(path, outcome.content);
134	      (outcome.conflicts > 0 ? conflicts : merged).push(path);
135	    }
136	  } finally {
137	    try {
138	      rmSync(scratch, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
139	    } catch {
140	      // The OS owns a temp directory it will not let go of.
141	    }
142	  }
