144	  // Then act. Writes first (parents included), deletions after — order only
145	  // matters where a release moves a directory's contents around, which no two
146	  // releases of this tree have done.
147	  for (const [path, content] of writes) {
148	    const destination = inside(path);
149	    if (destination === null) {
150	      // Unreachable through the checks above; the write half must stay honest.
151	      return { why: `\`${path}\` resolves outside the tree` };
152	    }
153	    mkdirSync(dirname(destination), { recursive: true });
154	    writeFileSync(destination, content);
155	  }
156	  for (const path of deletes) {
157	    try {
158	      rmSync(resolve(join(root, path)), { force: true });
159	    } catch (error) {
160	      return { why: `could not remove \`${path}\`: ${(error as Error).message}` };
161	    }
162	  }
163	
