165	}
166	
167	/**
168	 * The three-way merge of one path, as `git merge-file` answers it.
169	 *
170	 * The labels name the sides a person sees in the conflict markers, so a marker in a
171	 * freshly-updated tree reads as two named claims rather than two anonymous ones.
172	 * The exit code IS the conflict count (255 means the merge could not run); reading
173	 * it back as the outcome is what makes "merged cleanly" a measured fact.
174	 */
175	export function mergeFile(
176	  scratch: string,
177	  label: string,
178	  base: string,
179	  ours: string,
180	  theirs: string,
181	): { content: string; conflicts: number } | { why: string } {
182	  const oursPath = join(scratch, "ours");
183	  const basePath = join(scratch, "base");
184	  const theirsPath = join(scratch, "theirs");
185	  writeFileSync(oursPath, ours);
186	  writeFileSync(basePath, base);
187	  writeFileSync(theirsPath, theirs);
188	  const run = Bun.spawnSync({
189	    cmd: [
190	      "git", "merge-file",
191	      "-L", `${label} (ours)`,
192	      "-L", `${label} (base)`,
193	      "-L", `${label} (theirs)`,
194	      oursPath, basePath, theirsPath,
195	    ],
196	    stdout: "pipe",
197	    stderr: "pipe",
198	  });
199	  // `>0` is the conflict count and the file still carries the markers — the useful
200	  // case. `255` (and anything else) is a real failure, which must stop the run
201	  // rather than be read as "conflicted, carry on".
202	  const code = run.exitCode ?? 1;
203	  if (code === 255) {
204	    return { why: `git merge-file could not run: ${run.stderr?.toString("utf8").trim() || "no message"}` };
205	  }
206	  if (code < 0) {
207	    return { why: `the merge of ${label} was interrupted: ${run.stderr?.toString("utf8").trim() || "no message"}` };
208	  }
209	  return { content: readFileSync(oursPath, "utf8"), conflicts: code };
210	}

