1	#!/usr/bin/env bun
2	/**
3	 * dispatch_update.ts — the `!upgrade` bridge, as a script the workflow can run.
4	 *
5	 * A control command on a thread has to start a workflow by name — a comment fires
6	 * no event GitHub would act on — and the one module allowed to build that call is
7	 * `adapters/actions/dispatch-targets.ts` (see `tests/contract/dispatch-sites.test.ts`).
8	 * This script is the thin shell between the workflow's step and the bridge there:
9	 * the arguments come from the comment that asked, the decision is the bridge's.
10	 *
11	 * The caller's own token (`GH_TOKEN`) is what GitHub refuses to chain a run from —
12	 * that fact is the reason this file exists — and the bridge's dispatch is made
13	 * with it anyway, because `workflow_dispatch` is the documented exception that
14	 * still runs. A dispatch GitHub refuses is a red step, not a silent skip: a person
15	 * typed `!upgrade` and deserves to see that nothing started.
16	 *
17	 * Usage:
18	 *   dispatch_update.ts --repo OWNER/REPO [--source N]
19	 */
20	import { parseArgs } from "node:util";
21	import { dispatchUpdate } from "../../adapters/actions/dispatch-targets.ts";
22	import { defineScript } from "./lib/script-ref.ts";
23	
24	export interface DispatchUpdateArgs {
25	  /** `owner/name` of the repository to update — this one. */
26	  repo: string;
27	  /** The thread `!upgrade` came from, or nothing when started from the button. */
28	  source?: string;
29	}
30	
31	export const ref = defineScript<DispatchUpdateArgs>(import.meta.url);
32	
33	function main(): void {
34	  const { values } = parseArgs({
35	    args: Bun.argv.slice(2),
36	    options: {
37	      repo: { type: "string" },
38	      source: { type: "string" },
39	    },
40	  });
41	
42	  const repo = (values.repo ?? process.env.GITHUB_REPOSITORY ?? "").trim();
43	  if (!repo) {
44	    console.error("usage: dispatch_update.ts --repo OWNER/REPO [--source N]  (or set GITHUB_REPOSITORY)");
45	    process.exit(2);
46	  }
47	  const source = Number((values.source ?? "").trim() || "0");
48	
49	  const sent = dispatchUpdate(repo, Number.isInteger(source) ? source : 0);
50	  if (!sent) {
51	    console.error(
52	      `::error::could not dispatch the update workflow in ${repo}. Nothing was started — ` +
53	        "check the workflow name and the token, then run `!upgrade` again.",
54	    );
55	    process.exit(1);
56	  }
57	  console.error(`[dispatch-update] the update workflow was started${source > 0 ? ` and will answer in #${source}` : ""}`);
58	}
