2	/**
3	 * dispatch_cd.ts — start the deploy workflow for a merge that fired no push.
4	 *
5	 * A merge performed with `GITHUB_TOKEN` fires no `push`, so `deploy.on_merge`
6	 * never runs on its own. The bridge for that is `dispatchCd` in
7	 * `adapters/actions/dispatch-targets.ts`, which is also what the machinery's own
8	 * merges call; this script is the thin shell between a workflow's step and the
9	 * bridge, the way `dispatch_update.ts` is for `!upgrade`.
10	 *
11	 * The ref is the branch the merge landed on, not the merge commit: the deploy
12	 * runs against the branch's tip, which is what a push would have delivered. A
13	 * caller that needs the exact commit passes the branch it merged into and reads
14	 * the run's head SHA back from GitHub.
15	 *
16	 * Usage:
17	 *   dispatch_cd.ts --repo OWNER/REPO --ref BRANCH
18	 */
19	import { parseArgs } from "node:util";
20	import { dispatchCd } from "../../adapters/actions/dispatch-targets.ts";
21	import { defineScript } from "./lib/script-ref.ts";
22	
23	export interface DispatchCdArgs {
24	  /** `owner/name` of the repository — this one. */
25	  repo: string;
26	  /** The branch the merge landed on; the deploy runs against its tip. */
27	  ref: string;
28	}
29	
30	export const ref = defineScript<DispatchCdArgs>(import.meta.url);
31	
32	function main(): void {
33	  const { values } = parseArgs({
34	    args: Bun.argv.slice(2),
35	    options: {
36	      repo: { type: "string" },
37	      ref: { type: "string" },
38	    },
39	  });
